/// Two-level lookup; `cp` must be below 0x110000.
pub(crate) fn quick_check(cp: u32) -> u8 {
    let block = QUICK_CHECK_INDEX.get((cp >> QUICK_CHECK_SHIFT) as usize).copied().unwrap_or(0);
    let offset = (usize::from(block) << QUICK_CHECK_SHIFT) | (cp & ((1 << QUICK_CHECK_SHIFT) - 1)) as usize;
    QUICK_CHECK_BLOCKS.get(offset).copied().unwrap_or(0)
}

